const navItems = [
  ['/adminzz', 'Dashboard', LayoutDashboard],
  ['/adminzz/enquiries', 'Enquiries', ClipboardList],
  ['/adminzz/blogs', 'Blog Studio', BookOpen],
  ['/adminzz/catalogue', 'Catalogue', PackageOpen],
  ['/adminzz/settings', 'Settings', Settings],
] as const;

const articleCategories = ['AI & Automation', 'Cloud & Security', 'Data & Analytics', 'Leadership', 'Technology', 'Workforce Learning'];
const enquiryStatuses = ['new', 'contacted', 'qualified', 'proposal_sent', 'won', 'lost', 'spam'];
const priorities = ['low', 'normal', 'high', 'urgent'];

const formatDate = (value?: string | null, options: Intl.DateTimeFormatOptions = { dateStyle: 'medium', timeStyle: 'short' }) => (
  value ? new Intl.DateTimeFormat('en-IN', { ...options, timeZone: 'Asia/Kolkata' }).format(new Date(value)) : '—'
);

const toLocalInput = (value?: string | null) => value ? new Date(value).toLocaleString('sv-SE', { timeZone: 'Asia/Kolkata' }).replace(' ', 'T').slice(0, 16) : '';

const humanize = (value: string) => value.replace(/[_.]/g, ' ').replace(/\b\w/g, (letter) => letter.toUpperCase());

function sanitizePreviewHtml(value: string) {
  if (typeof DOMParser === 'undefined') return '';
  const documentFragment = new DOMParser().parseFromString(value || '', 'text/html');
  documentFragment.querySelectorAll('script, iframe, object, embed, form, input, button, link, meta, base').forEach((node) => node.remove());
  documentFragment.body.querySelectorAll('*').forEach((element) => {
    Array.from(element.attributes).forEach((attribute) => {
      const name = attribute.name.toLowerCase(); const content = attribute.value.trim().toLowerCase();
      if (name.startsWith('on') || name === 'srcdoc' || name === 'style' || ((name === 'href' || name === 'src') && content.startsWith('javascript:'))) element.removeAttribute(attribute.name);
    });
  });
  return documentFragment.body.innerHTML;
}

function useDismissibleLayer(open: boolean, onClose: () => void, container: React.RefObject<HTMLElement | null>, initialFocus?: React.RefObject<HTMLElement | null>) {
  useEffect(() => {
    if (!open) return undefined;
    const previouslyFocused = document.activeElement instanceof HTMLElement ? document.activeElement : null;
    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    window.requestAnimationFrame(() => initialFocus?.current?.focus());
    const dismiss = (event: KeyboardEvent) => {
      if (event.key === 'Escape') { onClose(); return; }
      if (event.key !== 'Tab') return;
      const focusable = Array.from(container.current?.querySelectorAll<HTMLElement>('a[href], button:not([disabled]), input:not([disabled]), select:not([disabled]), textarea:not([disabled]), [tabindex]:not([tabindex="-1"])') || []);
      if (!focusable.length) return;
      const first = focusable[0]; const last = focusable[focusable.length - 1];
      if (event.shiftKey && document.activeElement === first) { event.preventDefault(); last.focus(); }
      else if (!event.shiftKey && document.activeElement === last) { event.preventDefault(); first.focus(); }
    };
    document.addEventListener('keydown', dismiss);
    return () => {
      document.removeEventListener('keydown', dismiss);
      document.body.style.overflow = previousOverflow;
      previouslyFocused?.focus();
    };
  }, [container, initialFocus, onClose, open]);
}

function Notice({ error, success }: { error?: string; success?: string }) {
  if (!error && !success) return null;
  return <p className={`adminzz-notice ${error ? 'is-error' : 'is-success'}`} role={error ? 'alert' : 'status'}>{error || success}</p>;
}

function Loading() { return <div className="adminzz-loading" role="status">Loading secure workspace…</div>; }

function LoginPage({ onAuthenticated }: { onAuthenticated: (session: AdminSession) => void }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [busy, setBusy] = useState(false);
  const [error, setError] = useState('');
  const [recovery, setRecovery] = useState(false);
  const [notice, setNotice] = useState('');
  const submit = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError('');
    try {
      const result = await adminLogin(email, password);
      const fresh = await getAdminSession();
      if (!fresh) throw new Error('Your session could not be started. Please try again.');
      onAuthenticated(fresh);
    } catch (loginError) { setError(loginError instanceof Error ? loginError.message : 'Sign-in failed.'); }
    finally { setBusy(false); }
  };
  const recover = async (event: FormEvent) => {
    event.preventDefault(); setBusy(true); setError('');
    try { await adminRequest('/auth/forgot-password', { method: 'POST', body: { email } }); setNotice('If the owner account exists, a recovery email has been sent.'); }
    catch (requestError) { setError(requestError instanceof Error ? requestError.message : 'Recovery could not be started.'); }
    finally { setBusy(false); }
  };
  return <main className="adminzz-login"><section className="adminzz-login-card">
    <div className="adminzz-login-brand"><span>{brand}</span><strong>adminzz</strong></div>
    <p className="adminzz-eyebrow"><ShieldCheck size={15} /> Private administration</p>
    <h1>{recovery ? 'Recover access' : 'Sign in securely'}</h1>
    <p className="adminzz-muted">{recovery ? 'We will send a recovery link to the owner account.' : 'Use the owner email and password to manage TechnoEdge.'}</p>
    <form onSubmit={recovery ? recover : submit} className="adminzz-form" noValidate>
      <label>Owner email<input type="email" autoComplete="username" value={email} onChange={(event) => setEmail(event.target.value)} required /></label>
      {!recovery && <label>Password<div className="adminzz-password"><input type={showPassword ? 'text' : 'password'} autoComplete="current-password" value={password} onChange={(event) => setPassword(event.target.value)} required /><button type="button" onClick={() => setShowPassword(!showPassword)} aria-label={showPassword ? 'Hide password' : 'Show password'}><Eye size={17} /></button></div></label>}
      <button className="adminzz-button is-primary" disabled={busy}>{busy ? 'Please wait…' : recovery ? 'Send recovery email' : 'Sign in'}</button>
    </form>
    <Notice error={error} success={notice} />
    <button className="adminzz-link-button" type="button" onClick={() => { setRecovery(!recovery); setError(''); setNotice(''); }}>{recovery ? 'Back to sign in' : 'Forgot password?'}</button>
    <p className="adminzz-login-footnote">No public registration. Five unsuccessful attempts lock sign-in temporarily.</p>
  </section></main>;
}

function ResetPasswordPage() {
  const navigate = useNavigate();
  const [password, setPassword] = useState(''); const [confirm, setConfirm] = useState(''); const [error, setError] = useState(''); const [success, setSuccess] = useState('');
  const token = useMemo(() => new URLSearchParams(window.location.hash.replace(/^#/, '')).get('access_token') || '', []);
  const submit = async (event: FormEvent) => { event.preventDefault(); setError(''); if (password !== confirm) return setError('The passwords do not match.'); try { const data = await adminRequest<{ message: string }>('/auth/reset-password', { method: 'POST', body: { accessToken: token, password } }); setSuccess(data.message); window.setTimeout(() => navigate('/adminzz/login'), 1500); } catch (requestError) { setError(requestError instanceof Error ? requestError.message : 'The password could not be changed.'); } };
  return <main className="adminzz-login"><section className="adminzz-login-card"><div className="adminzz-login-brand"><span>{brand}</span><strong>adminzz</strong></div><h1>Set a new password</h1><p className="adminzz-muted">Use 14 or more characters with uppercase, lowercase, a number, and a symbol.</p><form className="adminzz-form" onSubmit={submit}><label>New password<input type="password" autoComplete="new-password" value={password} onChange={(event) => setPassword(event.target.value)} required /></label><label>Confirm password<input type="password" autoComplete="new-password" value={confirm} onChange={(event) => setConfirm(event.target.value)} required /></label><button className="adminzz-button is-primary">Save new password</button></form><Notice error={error} success={success} /></section></main>;
}

function Shell({ session, children, onSignOut }: { session: AdminSession; children: React.ReactNode; onSignOut: () => void }) {
  const location = useLocation(); const navigate = useNavigate(); const [open, setOpen] = useState(false);
  useEffect(() => { setOpen(false); }, [location.pathname, location.search]);
  useEffect(() => {
    if (!open) return undefined;
    const closeOnEscape = (event: KeyboardEvent) => { if (event.key === 'Escape') setOpen(false); };
    document.addEventListener('keydown', closeOnEscape);
    return () => document.removeEventListener('keydown', closeOnEscape);
  }, [open]);
  return <div className="adminzz-shell"><button type="button" className={`adminzz-nav-scrim ${open ? 'is-open' : ''}`} aria-label="Close navigation" onClick={() => setOpen(false)} /><aside id="adminzz-navigation" className={`adminzz-sidebar ${open ? 'is-open' : ''}`}><div className="adminzz-wordmark"><span>{brand}</span><strong>adminzz</strong></div><nav aria-label="Admin navigation">{navItems.map(([path, label, Icon]) => { const active = location.pathname === path || (path !== '/adminzz' && location.pathname.startsWith(path)); return <button key={path} className={active ? 'is-active' : ''} aria-current={active ? 'page' : undefined} onClick={() => { navigate(path); setOpen(false); }}><Icon size={18} aria-hidden="true" />{label}</button>; })}</nav><div className="adminzz-sidebar-bottom"><div className="adminzz-owner"><UserRound size={17} aria-hidden="true"/><span><strong>{session.profile.displayName || 'Owner'}</strong><small>{session.profile.email}</small></span></div><button className="adminzz-sign-out" onClick={onSignOut}><LogOut size={18} aria-hidden="true" />Sign Out</button></div></aside><div className="adminzz-main"><header className="adminzz-topbar"><button className="adminzz-menu" onClick={() => setOpen(!open)} aria-label={open ? 'Close navigation' : 'Open navigation'} aria-expanded={open} aria-controls="adminzz-navigation"><Menu aria-hidden="true" /></button><p><ShieldCheck size={16} aria-hidden="true"/> Secure owner workspace</p><span>IST · {session.profile.email}</span></header>{children}</div></div>;
}

function DashboardPage({ go }: { go: (path: string) => void }) {
  const [data, setData] = useState<any>(); const [error, setError] = useState('');
  useEffect(() => { adminRequest('/dashboard').then(setData).catch((requestError) => setError(requestError.message)); }, []);
  if (error) return <Page title="Dashboard"><Notice error={error} /></Page>;
  if (!data) return <Loading />;
  const cards = [
    ['New enquiries', data.enquiries.new, 'Unread enquiries needing review', '/adminzz/enquiries?status=new'],
    ['Follow-ups due', data.enquiries.follow_up_due, 'Scheduled contact tasks', '/adminzz/enquiries?sort=followUp'],
    ['Scheduled articles', data.blogs.scheduled, 'Upcoming publications', '/adminzz/blogs?tab=calendar'],
    ['Pending comments', data.comments.pending, 'Waiting for moderation', '/adminzz/blogs?tab=comments'],
  ];
  return <Page title="Dashboard" subtitle="The work that needs attention across enquiries, publishing, and system delivery."><div className="adminzz-metrics">{cards.map(([label, value, hint, path]) => <button key={label} className="adminzz-stat" onClick={() => go(path as string)}><span>{label}</span><strong>{value as number}</strong><small>{hint as string}<ChevronRight size={15}/></small></button>)}</div><div className="adminzz-grid two"><section className="adminzz-panel"><PanelHeading title="Enquiry pipeline" action="Open enquiries" onAction={() => go('/adminzz/enquiries')} /><div className="adminzz-pipeline">{['new', 'contacted', 'qualified', 'proposal_sent', 'won', 'lost'].map((status) => <div key={status}><span>{humanize(status)}</span><strong>{data.enquiries[status] || 0}</strong></div>)}</div></section><section className="adminzz-panel"><PanelHeading title="Contact activity · last 30 days" /><div className="adminzz-pipeline">{['call', 'email', 'whatsapp'].map((channel) => <div key={channel}><span>{humanize(channel)}</span><strong>{data.contactActions[channel] || 0}</strong></div>)}</div></section><section className="adminzz-panel"><PanelHeading title="Upcoming publications" action="Open calendar" onAction={() => go('/adminzz/blogs?tab=calendar')} />{data.upcoming.length ? <ul className="adminzz-simple-list">{data.upcoming.map((post: any) => <li key={post.post_id}><span><strong>{post.title}</strong><small>{formatDate(post.publish_at)}</small></span><button onClick={() => go(`/adminzz/blogs/${post.post_id}`)}>Edit</button></li>)}</ul> : <Empty text="No articles are scheduled." />}</section><section className="adminzz-panel"><PanelHeading title="Service health" /><div className="adminzz-health"><Health label="CRM queue" value={`${data.crm.pending || 0} pending`} kind={(data.crm.failed || data.crm.blocked) ? 'warn' : 'ok'} /><Health label="Email delivery" value={data.email.failed ? `${data.email.failed} failed` : 'Healthy'} kind={data.email.failed ? 'warn' : 'ok'} /><Health label="Scheduler" value="Timestamp driven" kind="ok" /><Health label="Database" value="Available" kind="ok" /></div></section></div><section className="adminzz-panel"><PanelHeading title="Recent administrative activity" onAction={() => go('/adminzz/settings?tab=audit')} action="View audit log" />{data.recentActivity.length ? <ul className="adminzz-simple-list">{data.recentActivity.map((item: any) => <li key={item.id}><span><strong>{humanize(item.action)}</strong><small>{item.actor_email || 'System'} · {formatDate(item.occurred_at)}</small></span><small>{item.entity_type}</small></li>)}</ul> : <Empty text="Activity will appear here once the workspace is used." />}</section></Page>;
}

function EnquiriesPage() {
  const location = useLocation(); const navigate = useNavigate(); const initial = useMemo(() => new URLSearchParams(location.search), []); const [query, setQuery] = useState(initial.get('query') || ''); const [status, setStatus] = useState(initial.get('status') || 'all'); const [priority, setPriority] = useState(initial.get('priority') || 'all'); const [sort, setSort] = useState(initial.get('sort') || 'received'); const [page, setPage] = useState(Number(initial.get('page')) || 1); const [rows, setRows] = useState<any[]>([]); const [pageData, setPageData] = useState<any>(); const [selected, setSelected] = useState<any>(); const [error, setError] = useState(''); const [loading, setLoading] = useState(true); const deferredQuery = useDeferredValue(query);
  const load = useCallback(async () => { setLoading(true); try { const params = new URLSearchParams({ page: String(page), pageSize: '25', status, priority, sort, ...(deferredQuery ? { query: deferredQuery } : {}) }); const result = await adminRequest<any>(`/enquiries?${params}`); setRows(result.data); setPageData(result.pagination); setError(''); } catch (requestError) { setError(requestError instanceof Error ? requestError.message : 'Enquiries could not be loaded.'); } finally { setLoading(false); } }, [deferredQuery, page, priority, sort, status]);
  useEffect(() => { load(); }, [load]);
  useEffect(() => { const params = new URLSearchParams(); if (query) params.set('query', query); if (status !== 'all') params.set('status', status); if (priority !== 'all') params.set('priority', priority); if (sort !== 'received') params.set('sort', sort); if (page > 1) params.set('page', String(page)); navigate({ search: params.toString() }, { replace: true }); }, [navigate, page, priority, query, sort, status]);
  const exportRows = (format: 'xlsx' | 'csv') => adminBinary(`/enquiries/export?format=${format}&status=${status}&priority=${priority}${query ? `&query=${encodeURIComponent(query)}` : ''}`, format).catch((requestError) => setError(requestError.message));
  const pageCount = Math.max(1, Math.ceil((pageData?.total || 0) / (pageData?.pageSize || 25)));
  return <Page title="Enquiries" subtitle="Every website enquiry, its source, follow-up state, and CRM delivery status in one secure workspace."><div className="adminzz-toolbar"><label className="adminzz-search"><Search size={17} aria-hidden="true"/><span className="adminzz-sr-only">Search enquiries</span><input placeholder="Search reference, name, email, organisation, course or phone" value={query} onChange={(event) => { setQuery(event.target.value); setPage(1); }} /></label><select aria-label="Filter by status" value={status} onChange={(event) => { setStatus(event.target.value); setPage(1); }}><option value="all">All statuses</option>{enquiryStatuses.map((item) => <option key={item} value={item}>{humanize(item)}</option>)}</select><select aria-label="Filter by priority" value={priority} onChange={(event) => { setPriority(event.target.value); setPage(1); }}><option value="all">All priorities</option>{priorities.map((item) => <option key={item} value={item}>{humanize(item)}</option>)}</select><select aria-label="Sort enquiries" value={sort} onChange={(event) => { setSort(event.target.value); setPage(1); }}><option value="received">Newest received</option><option value="followUp">Follow-up date</option><option value="updated">Recently updated</option><option value="priority">Priority</option><option value="status">Status</option></select><button className="adminzz-button" onClick={() => exportRows('xlsx')}><FileSpreadsheet size={16} aria-hidden="true"/>Excel</button><button className="adminzz-button" onClick={() => exportRows('csv')}><Download size={16} aria-hidden="true"/>CSV</button></div><Notice error={error} />{loading ? <Loading /> : <div className="adminzz-table-wrap" tabIndex={0} aria-label="Enquiry records"><table className="adminzz-table"><thead><tr><th>Enquiry</th><th>Service</th><th>Source</th><th>Status</th><th>Priority</th><th>Received</th><th><span className="adminzz-sr-only">Actions</span></th></tr></thead><tbody>{rows.map((row) => <tr key={row.submission_id} className={!row.is_read ? 'is-unread' : ''}><td><strong>{row.name || 'Unnamed visitor'}</strong><small>{row.company || row.email}<br />{row.reference}</small></td><td>{row.course_title || row.service || humanize(row.kind)}</td><td><small>{row.source_page || '—'}<br />{row.cta_id || '—'}</small></td><td><Badge value={row.status} /></td><td><Badge value={row.priority} /></td><td><small>{formatDate(row.received_at)}</small></td><td><button className="adminzz-icon-button" onClick={() => setSelected(row)} aria-label={`Open enquiry ${row.reference || ''}`}><ChevronRight size={18} aria-hidden="true"/></button></td></tr>)}</tbody></table>{!rows.length && <Empty text="No enquiries match these filters." />}</div>}<div className="adminzz-pagination"><span>{pageData?.total || 0} enquiry records · Page {Math.min(page, pageCount)} of {pageCount}</span><div><button className="adminzz-button" disabled={loading || page <= 1} onClick={() => setPage((current) => Math.max(1, current - 1))}>Previous</button><button className="adminzz-button" disabled={loading || page >= pageCount} onClick={() => setPage((current) => current + 1)}>Next</button></div></div>{selected && <EnquiryDrawer item={selected} close={() => setSelected(null)} onChanged={load} />}</Page>;
}

function EnquiryDrawer({ item, close, onChanged }: { item: any; close: () => void; onChanged: () => void }) {
  const [detail, setDetail] = useState<any>(); const [error, setError] = useState(''); const [note, setNote] = useState(''); const [busy, setBusy] = useState(false); const drawer = useRef<HTMLElement>(null); const closeButton = useRef<HTMLButtonElement>(null);
  useDismissibleLayer(true, close, drawer, closeButton);
  const load = useCallback(() => adminRequest<any>(`/enquiries/${item.submission_id}`).then(setDetail).catch((e) => setError(e.message)), [item.submission_id]); useEffect(() => { load(); }, [load]);
  const update = async (patch: any) => { setBusy(true); try { await adminRequest(`/enquiries/${item.submission_id}`, { method: 'PATCH', body: patch }); await load(); onChanged(); } catch (requestError) { setError(requestError instanceof Error ? requestError.message : 'Update failed.'); } finally { setBusy(false); } };
  const saveNote = async () => { if (!note.trim()) return; setBusy(true); try { await adminRequest(`/enquiries/${item.submission_id}/notes`, { method: 'POST', body: { note } }); setNote(''); await load(); } catch (requestError) { setError(requestError instanceof Error ? requestError.message : 'Note could not be saved.'); } finally { setBusy(false); } };
  const row = detail || item;
  return <div className="adminzz-drawer-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) close(); }}><aside ref={drawer} className="adminzz-drawer" role="dialog" aria-modal="true" aria-labelledby="adminzz-enquiry-title" aria-busy={busy}><header><div><p className="adminzz-eyebrow">{row.reference}</p><h2 id="adminzz-enquiry-title">{row.name || 'Website enquiry'}</h2></div><button ref={closeButton} className="adminzz-icon-button" onClick={close} aria-label="Close enquiry details"><X aria-hidden="true" /></button></header>{!detail ? <Loading /> : <div className="adminzz-drawer-body"><Notice error={error} /><section className="adminzz-contact-actions" aria-label="Contact actions"><a href={`mailto:${row.email}`}><Mail size={16} aria-hidden="true"/>Email</a>{row.phone && <a href={`tel:${row.phone}`}><Phone size={16} aria-hidden="true"/>Call</a>}{row.phone && <a href={`https://wa.me/${String(row.phone).replace(/\D/g, '')}`} target="_blank" rel="noreferrer"><MessageSquare size={16} aria-hidden="true"/>WhatsApp</a>}</section><div className="adminzz-fields"><label>Status<select value={row.status} disabled={busy} onChange={(event) => update({ status: event.target.value, isRead: true })}>{enquiryStatuses.map((value) => <option key={value} value={value}>{humanize(value)}</option>)}</select></label><label>Priority<select value={row.priority} disabled={busy} onChange={(event) => update({ priority: event.target.value })}>{priorities.map((value) => <option key={value} value={value}>{humanize(value)}</option>)}</select></label><label>Follow-up<input type="datetime-local" defaultValue={toLocalInput(row.follow_up_at)} onBlur={(event) => event.target.value && update({ followUpAt: event.target.value })} /></label><label>Tags<input defaultValue={(row.tags || []).join(', ')} onBlur={(event) => update({ tags: event.target.value.split(',').map((tag) => tag.trim()).filter(Boolean) })} /></label></div><section className="adminzz-detail-section"><h3>Contact and requirements</h3><dl><Detail label="Email" value={row.email}/><Detail label="Organisation" value={row.company}/><Detail label="Phone / WhatsApp" value={row.phone}/><Detail label="Course or service" value={row.course_title || row.service}/><Detail label="Learners" value={row.learners}/><Detail label="Delivery" value={row.delivery}/><Detail label="Requirements" value={row.notes}/><Detail label="Source" value={`${row.source_page || '—'} · ${row.cta_id || '—'}`}/><Detail label="CRM queue" value={row.crm_status || 'Pending configuration'}/></dl></section><section className="adminzz-detail-section"><h3>Internal notes</h3><textarea value={note} onChange={(event) => setNote(event.target.value)} placeholder="Add a private note" rows={4}/><button className="adminzz-button is-primary" disabled={busy || !note.trim()} onClick={saveNote}><Save size={16} aria-hidden="true"/>Save note</button><ul className="adminzz-timeline">{(row.notes || []).map((entry: any) => <li key={entry.note_id}><strong>{entry.author_email}</strong><p>{entry.note}</p><small>{formatDate(entry.created_at)}</small></li>)}</ul></section><section className="adminzz-detail-section"><h3>Activity</h3><ul className="adminzz-timeline">{(row.activity || []).map((entry: any) => <li key={entry.activity_id}><strong>{humanize(entry.action)}</strong><small>{formatDate(entry.created_at)}</small></li>)}</ul></section><button className="adminzz-button is-danger" disabled={busy} onClick={() => { if (window.confirm('Archive this enquiry? It can be restored later.')) void update({ archived: true }); }}><Archive size={16} aria-hidden="true"/>Archive enquiry</button></div>}</aside></div>;
}

function BlogStudioPage() {
  const location = useLocation(); const navigate = useNavigate(); const params = new URLSearchParams(location.search); const tab = params.get('tab') || 'articles'; const postId = location.pathname.match(/^\/adminzz\/blogs\/([^/]+)$/)?.[1];
  if (postId && postId !== 'new') return <ArticleEditor postId={postId} back={() => navigate('/adminzz/blogs')} />;
  if (postId === 'new') return <ArticleEditor back={() => navigate('/adminzz/blogs')} />;
  return <Page title="Blog Studio" subtitle="Articles, publishing dates, and visitor comments follow one editorial workflow."><div className="adminzz-tabs" role="tablist" aria-label="Blog Studio sections">{[['articles','Articles'], ['calendar','Publishing Calendar'], ['comments','Comments']].map(([key,label]) => <button key={key} role="tab" aria-selected={tab === key} className={tab === key ? 'is-active' : ''} onClick={() => navigate(`/adminzz/blogs?tab=${key}`)}>{label}</button>)}</div>{tab === 'articles' ? <ArticlesTab /> : tab === 'calendar' ? <CalendarTab /> : <CommentsTab />}</Page>;
}

function ArticlesTab() {
  const navigate = useNavigate(); const [data, setData] = useState<any>(); const [status, setStatus] = useState('all'); const [query, setQuery] = useState(''); const [error, setError] = useState(''); const load = useCallback(() => adminRequest<any>(`/blogs?status=${status}&query=${encodeURIComponent(query)}`).then(setData).catch((e) => setError(e.message)), [status, query]); useEffect(() => { load(); }, [load]);
  const duplicate = async (id: string) => { try { const next = await adminRequest<any>(`/blogs/${id}/duplicate`, { method: 'POST' }); navigate(`/adminzz/blogs/${next.post_id}`); } catch (e) { setError(e instanceof Error ? e.message : 'Duplicate failed.'); } };
  return <><div className="adminzz-toolbar"><label className="adminzz-search"><Search size={17} aria-hidden="true"/><span className="adminzz-sr-only">Search articles</span><input value={query} onChange={(event) => setQuery(event.target.value)} placeholder="Search title, slug, or author"/></label><select aria-label="Filter articles by status" value={status} onChange={(event) => setStatus(event.target.value)}><option value="all">All articles</option>{['draft','scheduled','published','archived'].map((item) => <option key={item} value={item}>{humanize(item)}</option>)}</select><button className="adminzz-button is-primary" onClick={() => navigate('/adminzz/blogs/new')}><Plus size={16} aria-hidden="true"/>New article</button></div><Notice error={error}/>{!data ? <Loading /> : <div className="adminzz-article-grid">{data.data.map((article: any) => <article key={article.post_id} className="adminzz-article-card">{article.featured_image_url ? <img src={article.featured_image_url} alt={article.featured_image_alt || ''}/> : <div className="adminzz-image-placeholder" aria-hidden="true"><BookOpen/></div>}<div><Badge value={article.status}/><h2>{article.title}</h2><p>{article.category} · {article.author_name}</p><small>{article.status === 'scheduled' ? `Scheduled ${formatDate(article.publish_at)}` : `Updated ${formatDate(article.updated_at)}`} · {article.pending_comments} pending comments</small><div className="adminzz-card-actions"><button onClick={() => navigate(`/adminzz/blogs/${article.post_id}`)}>Edit</button><button onClick={() => duplicate(article.post_id)}>Duplicate</button><a href={`/insights/${article.slug}`} target="_blank" rel="noreferrer">Preview</a></div></div></article>)}</div>}{data?.data?.length === 0 && <Empty text="No articles match these filters."/>}</>;
}

const blankArticle = { title: '', slug: '', excerpt: '', contentHtml: '<p>Start writing your article here.</p>', referenceTable: '', category: 'AI & Automation', tags: [], authorName: 'TechnoEdge Editorial Team', authorProfileUrl: '', reviewerName: '', reviewerProfileUrl: '', sourceUrls: [], reviewedAt: '', aiAssistanceDisclosure: '', featuredImageUrl: '', featuredImageAlt: '', imageCaption: '', seoTitle: '', metaDescription: '', canonicalUrl: '', status: 'draft', publishAt: '', isFeatured: false, indexable: false };

function ArticleEditor({ postId, back }: { postId?: string; back: () => void }) {
  const navigate = useNavigate(); const [activePostId, setActivePostId] = useState(postId); const [article, setArticle] = useState<any>(blankArticle); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [notice, setNotice] = useState(''); const [showPreview, setShowPreview] = useState(false); const editor = useRef<HTMLDivElement>(null); const initialized = useRef(false); const autosaveReady = useRef(false);
  const update = (key: string, value: any) => setArticle((previous: any) => ({ ...previous, [key]: value }));
  useEffect(() => { setActivePostId(postId); if (!postId) return; adminRequest<any>(`/blogs/${postId}`).then((data) => { setArticle({ ...blankArticle, ...data, contentHtml: data.content_html, referenceTable: data.reference_table, authorName: data.author_name, authorProfileUrl: data.author_profile_url, reviewerName: data.reviewer_name, reviewerProfileUrl: data.reviewer_profile_url, sourceUrls: data.source_urls || [], reviewedAt: toLocalInput(data.reviewed_at), aiAssistanceDisclosure: data.ai_assistance_disclosure, featuredImageUrl: data.featured_image_url, featuredImageAlt: data.featured_image_alt, imageCaption: data.image_caption, seoTitle: data.seo_title, metaDescription: data.meta_description, canonicalUrl: data.canonical_url, publishAt: toLocalInput(data.publish_at), isFeatured: data.is_featured, indexable: data.indexable }); initialized.current = false; autosaveReady.current = false; }).catch((e) => setError(e.message)); }, [postId]);
  useEffect(() => { if (editor.current && !initialized.current) { editor.current.innerHTML = article.contentHtml; initialized.current = true; } }, [article.contentHtml]);
  const save = async (intent?: string, quiet = false) => { setBusy(true); setError(''); const payload = { ...article, status: intent || article.status, contentHtml: editor.current?.innerHTML || article.contentHtml, tags: typeof article.tags === 'string' ? article.tags.split(',') : article.tags, publishAt: article.publishAt || undefined }; try { const result = activePostId ? await adminRequest<any>(`/blogs/${activePostId}`, { method: 'PUT', body: payload }) : await adminRequest<any>('/blogs', { method: 'POST', body: payload }); setArticle((current: any) => ({ ...current, ...result, contentHtml: result.content_html || payload.contentHtml })); initialized.current = false; setActivePostId(result.post_id); if (!quiet) setNotice(intent === 'scheduled' ? 'Article scheduled in IST.' : intent === 'published' ? 'Article is now published.' : 'Draft saved.'); if (!activePostId) navigate(`/adminzz/blogs/${result.post_id}`, { replace: true }); } catch (requestError) { setError(requestError instanceof Error ? requestError.message : 'Article could not be saved.'); } finally { setBusy(false); } };
  useEffect(() => {
    if (!activePostId) return undefined;
    if (!autosaveReady.current) { autosaveReady.current = true; return undefined; }
    const timer = window.setTimeout(() => { if (!busy && article.title.trim()) void save(undefined, true); }, 12000);
    return () => window.clearTimeout(timer);
  }, [article.title, article.excerpt, article.contentHtml, article.referenceTable, article.slug, article.category, article.tags, article.authorName, article.authorProfileUrl, article.reviewerName, article.reviewerProfileUrl, article.sourceUrls, article.reviewedAt, article.aiAssistanceDisclosure, article.featuredImageUrl, activePostId]);
  const upload = async (file?: File) => { if (!file) return; setBusy(true); try { const result = await adminRequest<any>('/media', { method: 'POST', headers: { 'Content-Type': file.type, 'X-File-Name': file.name }, body: file }); update('featuredImageUrl', result.publicUrl); setNotice('Image uploaded and stripped of metadata.'); } catch (requestError) { setError(requestError instanceof Error ? requestError.message : 'Image upload failed.'); } finally { setBusy(false); } };
  const command = (name: string, value?: string) => { document.execCommand(name, false, value); editor.current?.focus(); };
  return <Page title={postId ? 'Edit article' : 'New article'} subtitle="The public article layout stays consistent while you manage content, search details, and its publishing time."><div className="adminzz-editor-head"><button className="adminzz-button" onClick={back}><ArrowLeft size={16}/>Back to articles</button><div><button className="adminzz-button" onClick={() => setShowPreview(true)}><Eye size={16}/>Preview</button><button className="adminzz-button" disabled={busy} onClick={() => save('draft')}><Save size={16}/>Save draft</button><button className="adminzz-button" disabled={busy} onClick={() => save('scheduled')}><CalendarClock size={16}/>Schedule</button><button className="adminzz-button is-primary" disabled={busy} onClick={() => save('published')}><Send size={16}/>Publish</button></div></div><Notice error={error} success={notice}/><div className="adminzz-editor-layout"><div className="adminzz-editor-main"><label>Article title<input value={article.title} onChange={(event) => update('title', event.target.value)} placeholder="Clear, useful article title" /></label><label>Excerpt<textarea rows={3} value={article.excerpt} onChange={(event) => update('excerpt', event.target.value)} /></label><div className="adminzz-rich-toolbar" role="toolbar" aria-label="Article formatting"><button type="button" onClick={() => command('bold')}>Bold</button><button type="button" onClick={() => command('italic')}>Italic</button><button type="button" onClick={() => command('insertUnorderedList')}>List</button><button type="button" onClick={() => command('formatBlock', '<h2>')}>Heading</button><button type="button" onClick={() => { const url = window.prompt('Link URL'); if (url) document.execCommand('createLink', false, url); }}>Link</button></div><div ref={editor} className="adminzz-rich-editor" role="textbox" aria-label="Article body" aria-multiline="true" contentEditable suppressContentEditableWarning onInput={() => update('contentHtml', editor.current?.innerHTML || '')} /><label>Reference table<textarea rows={4} value={article.referenceTable || ''} onChange={(event) => update('referenceTable', event.target.value)} placeholder="Optional: Column 1 | Column 2" /></label></div><aside className="adminzz-editor-side"><h2>Publishing</h2><label>State<select value={article.status} onChange={(event) => update('status', event.target.value)}>{['draft','scheduled','published','archived'].map((item) => <option key={item} value={item}>{humanize(item)}</option>)}</select></label><label>Publish date and time (IST)<input type="datetime-local" value={article.publishAt || ''} onChange={(event) => update('publishAt', event.target.value)} /></label><label>Category<select value={article.category} onChange={(event) => update('category', event.target.value)}>{articleCategories.map((item) => <option key={item}>{item}</option>)}</select></label><hr/><h2>Editorial authority</h2><label>Author<input value={article.authorName || ''} onChange={(event) => update('authorName', event.target.value)} /></label><label>Author profile URL<input type="url" value={article.authorProfileUrl || ''} onChange={(event) => update('authorProfileUrl', event.target.value)} placeholder="https://…" /></label><label>Reviewer<input value={article.reviewerName || ''} onChange={(event) => update('reviewerName', event.target.value)} /></label><label>Reviewer profile URL<input type="url" value={article.reviewerProfileUrl || ''} onChange={(event) => update('reviewerProfileUrl', event.target.value)} placeholder="https://…" /></label><label>Material review date<input type="datetime-local" value={article.reviewedAt || ''} onChange={(event) => update('reviewedAt', event.target.value)} /></label><label>Approved source URLs<textarea rows={5} value={Array.isArray(article.sourceUrls) ? article.sourceUrls.join('\n') : article.sourceUrls || ''} onChange={(event) => update('sourceUrls', event.target.value)} placeholder="One HTTPS source per line" /></label><label>AI assistance disclosure<textarea rows={3} value={article.aiAssistanceDisclosure || ''} onChange={(event) => update('aiAssistanceDisclosure', event.target.value)} placeholder="Optional public disclosure" /></label><label>Tags<input value={Array.isArray(article.tags) ? article.tags.join(', ') : article.tags || ''} onChange={(event) => update('tags', event.target.value)} placeholder="AI, learning, leadership" /></label><label className="adminzz-check"><input type="checkbox" checked={Boolean(article.isFeatured)} onChange={(event) => update('isFeatured', event.target.checked)} /> Featured article</label><label className="adminzz-check"><input type="checkbox" checked={Boolean(article.indexable)} onChange={(event) => update('indexable', event.target.checked)} /> Allow search indexing after the authority gate passes</label><hr/><h2>Image</h2>{article.featuredImageUrl && <img className="adminzz-editor-image" src={article.featuredImageUrl} alt={article.featuredImageAlt || 'Current featured image'}/>}<input aria-label="Upload featured image" type="file" accept="image/jpeg,image/png,image/webp" onChange={(event) => upload(event.target.files?.[0])}/><label>Image URL<input value={article.featuredImageUrl || ''} onChange={(event) => update('featuredImageUrl', event.target.value)} /></label><label>Alt text<input value={article.featuredImageAlt || ''} onChange={(event) => update('featuredImageAlt', event.target.value)} /></label><label>Caption<input value={article.imageCaption || ''} onChange={(event) => update('imageCaption', event.target.value)} /></label><hr/><h2>Search</h2><label>Slug<input value={article.slug || ''} onChange={(event) => update('slug', event.target.value)} /></label><label>SEO title<input value={article.seoTitle || ''} onChange={(event) => update('seoTitle', event.target.value)} /></label><label>Meta description<textarea rows={3} value={article.metaDescription || ''} onChange={(event) => update('metaDescription', event.target.value)} /></label><label>Canonical URL<input value={article.canonicalUrl || ''} onChange={(event) => update('canonicalUrl', event.target.value)} /></label>{article.revisions?.length ? <><hr/><h2>Revisions</h2><ul className="adminzz-revisions">{article.revisions.map((revision: any) => <li key={revision.revision}>v{revision.revision} <button onClick={async () => { try { const restored = await adminRequest<any>(`/blogs/${postId}/revisions/${revision.revision}/restore`, { method: 'POST' }); setArticle((current: any) => ({ ...current, ...restored })); setNotice(`Restored revision ${revision.revision} as a draft.`); } catch (e) { setError(e instanceof Error ? e.message : 'Restore failed.'); } }}>Restore</button></li>)}</ul></> : null}</aside></div>{showPreview && <ArticlePreview article={{ ...article, contentHtml: editor.current?.innerHTML || article.contentHtml }} close={() => setShowPreview(false)} />}</Page>;
}

function ArticlePreview({ article, close }: { article: any; close: () => void }) {
  const preview = useRef<HTMLElement>(null); const closeButton = useRef<HTMLButtonElement>(null);
  const safeHtml = useMemo(() => sanitizePreviewHtml(article.contentHtml), [article.contentHtml]);
  useDismissibleLayer(true, close, preview, closeButton);
  return <div className="adminzz-preview-backdrop" onMouseDown={(event) => { if (event.target === event.currentTarget) close(); }}><section ref={preview} className="adminzz-preview" role="dialog" aria-modal="true" aria-labelledby="adminzz-preview-title"><button ref={closeButton} className="adminzz-icon-button" onClick={close} aria-label="Close article preview"><X aria-hidden="true"/></button><p>{article.category}</p><h1 id="adminzz-preview-title">{article.title || 'Untitled article'}</h1><p>{article.excerpt}</p>{article.featuredImageUrl && <img src={article.featuredImageUrl} alt={article.featuredImageAlt || ''}/>}<div dangerouslySetInnerHTML={{ __html: safeHtml }} /></section></div>;
}

function CalendarTab() {
  const [data, setData] = useState<any>(); const [view, setView] = useState<'calendar' | 'list'>('calendar'); const [visibleMonth, setVisibleMonth] = useState(() => new Date()); const [error, setError] = useState(''); const navigate = useNavigate();
  useEffect(() => { adminRequest<any>('/blogs?status=all&pageSize=100').then(setData).catch((requestError) => setError(requestError instanceof Error ? requestError.message : 'The publishing calendar could not be loaded.')); }, []);
  if (error) return <Notice error={error}/>;
  if (!data) return <Loading/>;
  const posts = data.data.filter((post: any) => post.status === 'scheduled' || post.status === 'published').sort((a: any,b: any) => new Date(a.publish_at || a.published_at).getTime() - new Date(b.publish_at || b.published_at).getTime());
  const today = new Date(); const first = new Date(visibleMonth.getFullYear(), visibleMonth.getMonth(), 1); const leading = first.getDay(); const lastDay = new Date(visibleMonth.getFullYear(), visibleMonth.getMonth() + 1, 0).getDate();
  const byDay = new Map<string, any[]>();
  posts.forEach((post: any) => { const date = new Date(post.publish_at || post.published_at); const key = new Intl.DateTimeFormat('en-CA', { timeZone: 'Asia/Kolkata' }).format(date); byDay.set(key, [...(byDay.get(key) || []), post]); });
  const dayCells = Array.from({ length: leading + lastDay }, (_, index) => index < leading ? null : index - leading + 1);
  const dayKey = (day: number) => `${visibleMonth.getFullYear()}-${String(visibleMonth.getMonth() + 1).padStart(2, '0')}-${String(day).padStart(2, '0')}`;
  const moveMonth = (offset: number) => setVisibleMonth((current) => new Date(current.getFullYear(), current.getMonth() + offset, 1));
  return <div className="adminzz-calendar"><section className="adminzz-panel"><div className="adminzz-calendar-head"><div><PanelHeading title="Publishing schedule · IST"/><p className="adminzz-muted">Select an article to change its date, publish it now, or return it to draft.</p></div><div className="adminzz-view-toggle" role="group" aria-label="Calendar view"><button aria-pressed={view === 'calendar'} className={view === 'calendar' ? 'is-active' : ''} onClick={() => setView('calendar')}>Calendar</button><button aria-pressed={view === 'list'} className={view === 'list' ? 'is-active' : ''} onClick={() => setView('list')}>List</button></div></div>{view === 'calendar' ? <><div className="adminzz-calendar-navigation"><button className="adminzz-icon-button" onClick={() => moveMonth(-1)} aria-label="Previous month"><ChevronLeft aria-hidden="true"/></button><h3 className="adminzz-calendar-month" aria-live="polite">{new Intl.DateTimeFormat('en-IN', { month: 'long', year: 'numeric', timeZone: 'Asia/Kolkata' }).format(visibleMonth)}</h3><button className="adminzz-icon-button" onClick={() => moveMonth(1)} aria-label="Next month"><ChevronRight aria-hidden="true"/></button><button className="adminzz-button" disabled={visibleMonth.getFullYear() === today.getFullYear() && visibleMonth.getMonth() === today.getMonth()} onClick={() => setVisibleMonth(new Date())}>Today</button></div><div className="adminzz-month-grid" tabIndex={0} aria-label="Publishing calendar">{['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map((day) => <strong key={day}>{day}</strong>)}{dayCells.map((day, index) => <div className="adminzz-day-cell" key={`${day || 'blank'}-${index}`}>{day && <><span>{day}</span>{(byDay.get(dayKey(day)) || []).map((post) => <button key={post.post_id} title={post.title} onClick={() => navigate(`/adminzz/blogs/${post.post_id}`)}>{post.status === 'scheduled' ? 'Scheduled' : 'Published'} · {post.title}</button>)}</>}</div>)}</div></> : posts.length ? <ul className="adminzz-schedule-list">{posts.map((post: any) => <li key={post.post_id}><time>{formatDate(post.publish_at || post.published_at)}</time><span><Badge value={post.status}/><strong>{post.title}</strong></span><button onClick={() => navigate(`/adminzz/blogs/${post.post_id}`)}>Open</button></li>)}</ul> : <Empty text="Your next scheduled article will appear here."/>}</section></div>;
}

function CommentsTab() { const [data, setData] = useState<any>(); const [status, setStatus] = useState('pending'); const [checked, setChecked] = useState<string[]>([]); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const load = useCallback(() => adminRequest<any>(`/comments?status=${status}`).then((result) => { setData(result); setChecked([]); setError(''); }).catch((e) => setError(e.message)), [status]); useEffect(() => { setData(undefined); load(); }, [load]); const moderate = async (nextStatus: string, ids = checked) => { if (!ids.length) return; setBusy(true); try { await adminRequest('/comments', { method: 'PATCH', body: { commentIds: ids, status: nextStatus } }); await load(); } catch (e) { setError(e instanceof Error ? e.message : 'Moderation failed.'); } finally { setBusy(false); } }; return <><div className="adminzz-toolbar"><select aria-label="Filter comments by status" value={status} onChange={(event) => setStatus(event.target.value)}>{['pending','approved','rejected','spam','archived','all'].map((item) => <option key={item} value={item}>{humanize(item)}</option>)}</select>{checked.length > 0 && <><button disabled={busy} className="adminzz-button is-primary" onClick={() => moderate('approved')}><Check size={16} aria-hidden="true"/>Approve ({checked.length})</button><button disabled={busy} className="adminzz-button" onClick={() => moderate('rejected')}>Reject</button><button disabled={busy} className="adminzz-button is-danger" onClick={() => moderate('spam')}>Spam</button><button disabled={busy} className="adminzz-button" onClick={() => moderate('archived')}><Archive size={16} aria-hidden="true"/>Archive</button></>}</div><Notice error={error}/>{!data ? <Loading/> : <div className="adminzz-comment-list" aria-busy={busy}>{data.data.map((comment: any) => <article key={comment.comment_id}><input aria-label={`Select comment from ${comment.visitor_name}`} type="checkbox" checked={checked.includes(comment.comment_id)} onChange={(event) => setChecked((current) => event.target.checked ? [...current, comment.comment_id] : current.filter((id) => id !== comment.comment_id))}/><div><a href={`/insights/${comment.article_slug}`} target="_blank" rel="noreferrer">{comment.article_title}</a><h3>{comment.visitor_name} <small>{comment.visitor_email}</small></h3><p>{comment.message}</p><small>{formatDate(comment.created_at)}</small></div><div className="adminzz-comment-actions"><Badge value={comment.status}/><button disabled={busy} onClick={() => moderate('approved', [comment.comment_id])}>Approve</button><button disabled={busy} onClick={() => moderate('rejected', [comment.comment_id])}>Reject</button><button disabled={busy} onClick={() => moderate('spam', [comment.comment_id])}>Spam</button><button disabled={busy} onClick={() => moderate('archived', [comment.comment_id])}>Archive</button></div></article>)}</div>}{data?.data?.length === 0 && <Empty text="No comments in this view."/>}</>; }

function SettingsPage({ session }: { session: AdminSession }) { const location = useLocation(); const navigate = useNavigate(); const tab = new URLSearchParams(location.search).get('tab') || 'profile'; const [data, setData] = useState<any>(); const [error, setError] = useState(''); const [notice, setNotice] = useState(''); const load = useCallback(() => adminRequest<any>('/settings').then((result) => { setData(result); setError(''); }).catch((e) => setError(e.message)), []); useEffect(() => { load(); }, [load]); const save = async (body: any) => { try { await adminRequest('/settings', { method: 'PATCH', body }); setNotice('Settings saved.'); setError(''); load(); } catch (e) { setError(e instanceof Error ? e.message : 'Settings could not be saved.'); } }; const tabs = [['profile','Profile'],['security','Security'],['notifications','Notifications'],['integrations','Integrations'],['system','System'],['audit','Audit Log']]; return <Page title="Settings" subtitle="Owner details, system connections, security history, and the immutable activity record."><div className="adminzz-tabs" role="tablist" aria-label="Settings sections">{tabs.map(([key,label]) => <button key={key} role="tab" aria-selected={tab === key} className={tab === key ? 'is-active' : ''} onClick={() => navigate(`/adminzz/settings?tab=${key}`)}>{label}</button>)}</div><Notice error={error} success={notice}/>{!data ? <Loading/> : tab === 'profile' || tab === 'notifications' ? <SettingsForm data={data} tab={tab} save={save} /> : tab === 'security' ? <SecurityPanel data={data} session={session} /> : tab === 'integrations' ? <IntegrationsPanel data={data} /> : tab === 'system' ? <SystemPanel data={data} /> : <AuditPanel />}</Page>; }

function SettingsForm({ data, tab, save }: { data: any; tab: string; save: (body: any) => void }) { const [form, setForm] = useState({ displayName: data.profile.display_name || '', defaultAuthor: data.profile.default_author || '', recipientEmail: data.notifications.recipient_email || '', enquiryEmailEnabled: data.notifications.enquiry_email_enabled, commentEmailEnabled: data.notifications.comment_email_enabled, publishingEmailEnabled: data.notifications.publishing_email_enabled }); return <form className="adminzz-panel adminzz-settings-form" onSubmit={(event) => { event.preventDefault(); save(form); }}>{tab === 'profile' && <><label>Owner email<input value={data.profile.email} disabled /></label><label>Owner display name<input value={form.displayName} onChange={(event) => setForm({ ...form, displayName: event.target.value })}/></label><label>Default blog author<input value={form.defaultAuthor} onChange={(event) => setForm({ ...form, defaultAuthor: event.target.value })}/></label></>}{tab === 'notifications' && <><label>Enquiry notification recipient<input type="email" value={form.recipientEmail} onChange={(event) => setForm({ ...form, recipientEmail: event.target.value })}/></label><label className="adminzz-check"><input type="checkbox" checked={form.enquiryEmailEnabled} onChange={(event) => setForm({ ...form, enquiryEmailEnabled: event.target.checked })}/>New enquiry email</label><label className="adminzz-check"><input type="checkbox" checked={form.commentEmailEnabled} onChange={(event) => setForm({ ...form, commentEmailEnabled: event.target.checked })}/>Pending comment email</label><label className="adminzz-check"><input type="checkbox" checked={form.publishingEmailEnabled} onChange={(event) => setForm({ ...form, publishingEmailEnabled: event.target.checked })}/>Scheduled publication email</label></>}<button className="adminzz-button is-primary"><Save size={16}/>Save settings</button></form>; }

function SecurityPanel({ data }: { data: any; session: AdminSession }) { const [currentPassword, setCurrentPassword] = useState(''); const [nextPassword, setNextPassword] = useState(''); const [error, setError] = useState(''); const [notice, setNotice] = useState(''); const submit = async (event: FormEvent) => { event.preventDefault(); try { const result = await adminRequest<any>('/settings/password', { method: 'POST', body: { currentPassword, nextPassword } }); setNotice(result.message); setError(''); } catch (e) { setError(e instanceof Error ? e.message : 'Password could not be changed.'); } }; return <div className="adminzz-grid two"><section className="adminzz-panel"><PanelHeading title="Password"/><p className="adminzz-muted">Use 14+ characters with uppercase, lowercase, a number, and a symbol. Changing it signs out all sessions.</p><form className="adminzz-form" onSubmit={submit}><label>Current password<input type="password" autoComplete="current-password" value={currentPassword} onChange={(event) => setCurrentPassword(event.target.value)}/></label><label>New password<input type="password" autoComplete="new-password" value={nextPassword} onChange={(event) => setNextPassword(event.target.value)}/></label><button className="adminzz-button is-primary"><KeyRound size={16}/>Change password</button></form><Notice error={error} success={notice}/></section><section className="adminzz-panel"><PanelHeading title="Sessions"/>{data.sessions.map((item: any) => <div className="adminzz-session" key={item.session_id}><strong>{item.active ? 'Active session' : 'Closed session'}</strong><span>{formatDate(item.last_seen_at)}<br/>{item.user_agent || 'Unknown device'}</span></div>)}</section><section className="adminzz-panel"><PanelHeading title="Login history"/>{data.loginHistory.map((entry: any, index: number) => <div className="adminzz-session" key={index}><strong>{entry.succeeded ? 'Successful sign in' : 'Failed sign in'}</strong><span>{formatDate(entry.occurred_at)}</span></div>)}</section></div>; }

function IntegrationsPanel({ data }: { data: any }) { return <section className="adminzz-panel"><PanelHeading title="Integration status"/><div className="adminzz-health">{Object.entries(data.integrations).map(([key, value]: any) => <Health key={key} label={humanize(key)} value={value.configured ? value.state || 'Configured' : value.state || 'Not configured'} kind={value.configured ? 'ok' : 'warn'}/>)}</div><p className="adminzz-muted">Secrets are never displayed here. CRM connection fields will appear once the CRM integration is configured.</p></section>; }
function SystemPanel({ data }: { data: any }) { return <section className="adminzz-panel"><PanelHeading title="System health"/><div className="adminzz-health">{Object.entries(data.system).map(([key, value]: any) => <Health key={key} label={humanize(key)} value={value.ok ? value.mode || 'Healthy' : 'Needs attention'} kind={value.ok ? 'ok' : 'warn'}/>)}</div></section>; }
function AuditPanel() { const [data, setData] = useState<any>(); const [query, setQuery] = useState(''); const [action, setAction] = useState('all'); const [page, setPage] = useState(1); const [error, setError] = useState(''); const deferredQuery = useDeferredValue(query); const load = useCallback(() => { setData(undefined); const params = new URLSearchParams({ query: deferredQuery, page: String(page), pageSize: '50' }); if (action !== 'all') params.set('action', action); adminRequest<any>(`/audit?${params}`).then((result) => { setData(result); setError(''); }).catch((requestError) => setError(requestError instanceof Error ? requestError.message : 'The audit log could not be loaded.')); }, [action, deferredQuery, page]); useEffect(() => { load(); }, [load]); const pageCount = Math.max(1, Math.ceil((data?.pagination?.total || 0) / (data?.pagination?.pageSize || 50))); return <section className="adminzz-panel"><div className="adminzz-toolbar"><label className="adminzz-search"><Search size={17} aria-hidden="true"/><span className="adminzz-sr-only">Search audit entries</span><input value={query} onChange={(event) => { setQuery(event.target.value); setPage(1); }} placeholder="Search audit entries"/></label><select aria-label="Filter audit action" value={action} onChange={(event) => { setAction(event.target.value); setPage(1); }}><option value="all">All actions</option>{['auth.login_succeeded','auth.login_failed','auth.password_changed','blog.created','blog.draft','blog.scheduled','blog.published','blog.archived','comments.approved','comments.rejected','comments.spam','enquiry.updated','enquiry.note_added','enquiries.exported','catalogue.import_completed','settings.updated'].map((item) => <option key={item} value={item}>{humanize(item)}</option>)}</select></div><Notice error={error}/>{!data ? <Loading/> : <><div className="adminzz-table-wrap" tabIndex={0} aria-label="Administrative audit log"><table className="adminzz-table"><thead><tr><th>Action</th><th>Actor</th><th>Entity</th><th>When</th></tr></thead><tbody>{data.data.map((entry: any) => <tr key={entry.id}><td>{humanize(entry.action)}</td><td>{entry.actor_email || 'System'}</td><td>{entry.entity_type} {entry.entity_id ? `· ${entry.entity_id}` : ''}</td><td>{formatDate(entry.occurred_at)}</td></tr>)}</tbody></table>{data.data.length === 0 && <Empty text="No audit entries match these filters."/>}</div><div className="adminzz-pagination"><span>{data.pagination?.total || 0} entries · Page {Math.min(page, pageCount)} of {pageCount}</span><div><button className="adminzz-button" disabled={page <= 1} onClick={() => setPage((current) => Math.max(1, current - 1))}>Previous</button><button className="adminzz-button" disabled={page >= pageCount} onClick={() => setPage((current) => current + 1)}>Next</button></div></div></>}</section>; }

function Page({ title, subtitle, children }: { title: string; subtitle?: string; children: React.ReactNode }) { return <main className="adminzz-page"><header className="adminzz-page-heading"><p className="adminzz-eyebrow">{brand} adminzz</p><h1>{title}</h1>{subtitle && <p>{subtitle}</p>}</header>{children}</main>; }
function PanelHeading({ title, action, onAction }: { title: string; action?: string; onAction?: () => void }) { return <header className="adminzz-panel-heading"><h2>{title}</h2>{action && <button onClick={onAction}>{action}<ChevronRight size={15}/></button>}</header>; }
function Empty({ text }: { text: string }) { return <div className="adminzz-empty"><CircleAlert size={20}/><p>{text}</p></div>; }
function Badge({ value }: { value?: string }) { return <span className={`adminzz-badge ${value || ''}`}>{humanize(value || '—')}</span>; }
function Health({ label, value, kind }: { label: string; value: string; kind: 'ok' | 'warn' }) { return <div className="adminzz-health-row"><span><i className={kind}/>{label}</span><strong>{value}</strong></div>; }
function Detail({ label, value }: { label: string; value?: string | number | null }) { return <><dt>{label}</dt><dd>{value || '—'}</dd></>; }

export default function AdminApp() {
  const location = useLocation(); const navigate = useNavigate(); const [session, setSession] = useState<AdminSession | null | undefined>();
  const isLogin = location.pathname === '/adminzz/login'; const isReset = location.pathname === '/adminzz/reset-password';
  useEffect(() => { if (isLogin || isReset) { setSession(null); return; } getAdminSession().then(setSession); }, [isLogin, isReset]);
  useEffect(() => { const expire = () => setSession(null); window.addEventListener('adminzz:unauthorized', expire); return () => window.removeEventListener('adminzz:unauthorized', expire); }, []);
  const signedIn = (next: AdminSession) => { setSession(next); navigate('/adminzz', { replace: true }); };
  const signOut = async () => { await adminLogout().catch(() => {}); setSession(null); navigate('/adminzz/login', { replace: true }); };
  if (isReset) return <ResetPasswordPage/>;
  if (isLogin) return <LoginPage onAuthenticated={signedIn}/>;
  if (session === undefined) return <Loading/>;
  if (!session) return <Navigate to="/adminzz/login" replace />;
  const go = (path: string) => navigate(path);
  return <Shell session={session} onSignOut={signOut}>{location.pathname === '/adminzz' ? <DashboardPage go={go}/> : location.pathname.startsWith('/adminzz/enquiries') ? <EnquiriesPage/> : location.pathname.startsWith('/adminzz/blogs') ? <BlogStudioPage/> : location.pathname.startsWith('/adminzz/catalogue') ? <Page title="Catalogue" subtitle="Validate course data before it changes the catalogue, then confirm one transactional import."><ImportCentre/></Page> : <SettingsPage session={session}/>}</Shell>;
}
